export function openBatchAppearance(api){
 const {reference,openDialog,closeDialog,toast,esc,available,chosen,request,apply}=api;if(!reference)return;
 openDialog('批量应用样式与内容',`<p>以当前配置 <strong>${esc(reference.product)} / ${esc(reference.name)}</strong> 为基准。</p><label class="field">应用范围<select id="style-scope"><option value="selected">左侧已勾选 ${chosen().length} 套</option><option value="all">全部 ${available().length} 套配置</option></select></label><div class="style-options"><label><input id="style-colors" type="checkbox" checked> 全部配色（主题、背景、文字、数量、升级说明及服务承诺）</label><label><input id="style-format" type="checkbox" checked> 全部编辑格式（文字框宽高与位置、字体、局部样式、模块布局、图片位置与大小、顺序和显示开关）</label><label><input id="style-images" type="checkbox"> 仅同步机箱位置、大小和显示开关（已包含在全部格式内）</label><label><input id="style-asset" type="checkbox"> 批量更换机箱图片</label><label><input id="style-addons" type="checkbox"> 同步加购与选配（整组商品、数量、加购总价、描述和说明）</label><label><input id="style-benefits" type="checkbox"> 同步福利点</label></div><p id="style-content-preview" class="hint" role="status"></p><div id="style-asset-panel" class="hidden"><div class="batch-case-preview"><img id="style-asset-preview" alt="将应用的机箱图片"><span id="style-asset-name" class="hint"></span></div><div class="actions"><button id="style-asset-current">使用当前配置图片</button><button id="style-asset-upload">选择新机箱图片</button><input id="style-asset-file" type="file" accept="image/png,image/jpeg" hidden></div><p class="hint">支持 PNG、JPG，最大 24MB。所有目标使用同一张图片；位置、大小及显示状态由全部格式或机箱格式选项控制。</p></div><p class="hint">保留各配置的主机配件、数量、售价及 SPU/SKU。加购与福利仅在勾选时替换，未勾选的文案保留。未勾选更换图片时保留原机箱素材；目标独有的文字模块保留。两种版式的文本框与自由布局一起同步；附加图片按对应素材或顺序匹配位置与大小，保留目标原图。</p><div id="style-scope-preview" class="hint"></div><div class="actions"><button id="style-apply" class="primary">应用到所选配置</button></div>`);
 const $=s=>document.querySelector(s),root=$('#style-apply'),dialog=root.closest('dialog');let imageUrl=reference.caseImage||'',base64=null,loading=false,saving=false,generation=0;
 const targets=()=>$('#style-scope').value==='all'?available():chosen();
 const update=()=>{if(!root.isConnected)return;const list=targets();if($('#style-format').checked)$('#style-images').checked=true;$('#style-images').disabled=$('#style-format').checked||saving;$('#style-content-preview').textContent=[$('#style-addons').checked?`将用当前配置的 ${reference.addons?.length||0} 条加购替换目标已有加购（空列表会清空）。目标没有相同原配件关联时，复制为独立加购。`:'',$('#style-benefits').checked?`将用当前配置的 ${reference.benefits?.length||0} 条福利点替换目标已有福利点（空列表会清空）。`:''].filter(Boolean).join(' ');const asset=$('#style-asset').checked,any=['colors','format','images','asset','addons','benefits'].some(k=>$('#style-'+k).checked);root.disabled=saving||loading||!list.length||!any||(asset&&!imageUrl);root.textContent=saving?'正在应用…':`应用到 ${list.length} 套配置`;$('#style-asset-panel').classList.toggle('hidden',!asset);$('#style-scope-preview').textContent=list.slice(0,12).map(c=>`${c.product} / ${c.name}`).join('、')+(list.length>12?` 等 ${list.length} 套`:'');};
 const preview=label=>{const img=$('#style-asset-preview');img.hidden=!imageUrl;if(imageUrl)img.src=imageUrl;else img.removeAttribute('src');$('#style-asset-name').textContent=label;update();};
 for(const el of document.querySelectorAll('#dialog-body input[type="checkbox"],#style-scope'))el.onchange=update;
 $('#style-asset-current').onclick=()=>{generation++;loading=false;base64=null;imageUrl=reference.caseImage||'';$('#style-asset-file').value='';preview(imageUrl?'当前配置的机箱图片':'当前配置没有机箱图片，请选择新图片');};
 $('#style-asset-upload').onclick=()=>$('#style-asset-file').click();
 $('#style-asset-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++generation;loading=true;imageUrl='';base64=null;preview('正在读取图片…');try{if(file.size>24*1024*1024)throw Error('素材请小于 24MB');if(!['image/png','image/jpeg'].includes(file.type))throw Error('请选择 PNG 或 JPG 图片');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('读取图片失败'));r.readAsDataURL(file);});const img=new Image();img.src=data;await img.decode();if(token!==generation||!root.isConnected)return;imageUrl=data;base64=data.split(',')[1];loading=false;preview(file.name);}catch(e){if(token!==generation||!root.isConnected)return;loading=false;preview('图片无法使用，请重新选择');toast(e.message);}};
 preview(imageUrl?'当前配置的机箱图片':'当前配置没有机箱图片，请选择新图片');
 root.onclick=async()=>{if(root.disabled)return;const configs=targets(),options=Object.fromEntries(['colors','format','images','asset','addons','benefits'].map(k=>[k,$('#style-'+k).checked]));let url=imageUrl;saving=true;update();const controls=[...document.querySelectorAll('#dialog-body input,#dialog-body select,#dialog-body button')];controls.forEach(el=>el.disabled=true);try{if(options.asset&&base64){const result=await request('/api/asset',{method:'POST',body:JSON.stringify({base64})});url=result.url;}if(!root.isConnected||!dialog.open)return;if(configs.some(c=>!available().includes(c)))throw Error('配置已变化，请重新打开批量设置');apply(reference,configs,options,url);closeDialog();toast(`已应用到 ${configs.length} 套配置，正在保存并更新图片`);}catch(e){toast(e.message);}finally{saving=false;if(root.isConnected){controls.forEach(el=>el.disabled=false);update();}}};
}
